<?php require_once __DIR__.'/../../models/InscripcionModel.php';$ins=es_estudiante()?[]:(new InscripcionModel($pdo))->obtenerTodas();include __DIR__.'/../layouts/header.php';$puedeGestionar=puede_gestionar_academico();?><div class="toolbar"><div><h1 class="page-title">Notas y calificaciones</h1><p class="subtitle">Registro académico por inscripción.</p></div><?php if($puedeGestionar):?><a class="btn btn-primary" href="?accion=crear">+ Registrar nota</a><?php endif;?></div><div class="card"><div class="card-body"><input class="search" data-search="#tabla" placeholder="Buscar estudiante o curso..."><div class="table-wrap"><table class="table" id="tabla"><thead><tr><th>Estudiante</th><th>Curso</th><th>Tipo</th><th>Nota</th><th>Fecha</th><?php if($puedeGestionar):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?=e($r['estudiante'])?></td><td><?=e($r['codigo'])?></td><td><?=e($r['tipo'])?></td><td><span class="badge <?=((float)$r['nota']>=60?'badge-success':'badge-danger')?>"><?=number_format($r['nota'],2)?></span></td><td><?=e($r['fecha'])?></td><?php if($puedeGestionar):?><td><div class="actions"><a class="btn btn-light btn-sm" href="?accion=editar&id=<?=$r['id_calificacion']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar calificación?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$r['id_calificacion']?>"><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div></div><?php if($puedeGestionar && $accion!=='listar'):?><div class="card" style="margin-top:18px"><div class="card-body"><h2 style="margin-top:0"><?= $registro?'Editar':'Registrar'?> calificación</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><div class="grid grid-2"><div class="form-group"><label class="form-label">Inscripción</label><select required name="id_inscripcion"><?php foreach($ins as $i):?><option value="<?=$i['id_inscripcion']?>" <?=($registro['id_inscripcion']??'')==$i['id_inscripcion']?'selected':''?>><?=e($i['estudiante'].' · '.$i['codigo'].' · '.$i['nombre_curso'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Tipo de evaluación</label><input required name="tipo" value="<?=e($registro['tipo']??'Parcial')?>"></div><div class="form-group"><label class="form-label">Nota (0 a 100)</label><input required type="number" min="0" max="100" step="0.01" name="nota" value="<?=e($registro['nota']??'')?>"></div><div class="form-group"><label class="form-label">Fecha</label><input required type="date" name="fecha" value="<?=e($registro['fecha']??date('Y-m-d'))?>"></div></div><div class="form-group"><label class="form-label">Observación</label><input name="observacion" value="<?=e($registro['observacion']??'')?>"></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/calificaciones.php">Cancelar</a></div></form></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
